+      });
+      this.logger.log(`push token cleared: user=${userId} reason=DeviceNotRegistered`);
+    } catch (err) {
+      this.logger.warn(`push token clear failed: user=${userId} error=${errorName(err)}`);
+    }
+  }
+
+  private alertProviderNotConfigured(): void {
