+function expo(send: SendImpl = async (m) => m.map(() => ({ status: 'ok', id: 'x' }))) {
+  let n = 0;
+  return {
+    send: jest.fn<Promise<ExpoPushTicket[]>, [ExpoPushMessage[], AbortSignal]>(async (m, s) => {
+      const out = await send(m, s);
